"""Print the paths and ids of a gov retrieve --json envelope read from standard input."""
import json
import sys

text = sys.stdin.read()
start = text.find("{")
envelope = json.loads(text[start:]) if start >= 0 else {}
result = envelope.get("result", envelope) if isinstance(envelope, dict) else {}
for item in result.get("evidence") or []:
    print(item.get("path"), item.get("id") or item.get("chunk_id"))
for key in ("continue", "continuation", "token", "next"):
    if result.get(key):
        print(key, result[key])
print("ok", envelope.get("ok"), "error", (envelope.get("error") or {}).get("code") if isinstance(envelope, dict) else None)
